    blurb: "Space Trader \u043E\u043D\u043E\u0432\u043B\u044E\u0454\u0442\u044C\u0441\u044F \u0441\u0430\u043C \u0456\u0437 \u0440\u0435\u043B\u0456\u0437\u0456\u0432 \u043D\u0430 GitHub. \u041D\u043E\u0432\u0430 \u0432\u0435\u0440\u0441\u0456\u044F \u0442\u0438\u0445\u043E \u0437\u0430\u0432\u0430\u043D\u0442\u0430\u0436\u0443\u0454\u0442\u044C\u0441\u044F \u0443 \u0444\u043E\u043D\u0456 \u0456 \u0432\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u044E\u0454\u0442\u044C\u0441\u044F, \u0449\u043E\u0439\u043D\u043E \u0432\u0438 \u0432\u0438\u0439\u0434\u0435\u0442\u0435 \u0437 \u0433\u0440\u0438 \u2014 \u043D\u0456\u0447\u043E\u0433\u043E \u043F\u0435\u0440\u0435\u0432\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u044E\u0432\u0430\u0442\u0438 \u0432\u0440\u0443\u0447\u043D\u0443 \u043D\u0435 \u0442\u0440\u0435\u0431\u0430.",
    idle: "\u0429\u0435 \u043D\u0435 \u043F\u0435\u0440\u0435\u0432\u0456\u0440\u044F\u043B\u0438.",
    checking: "\u041F\u0435\u0440\u0435\u0432\u0456\u0440\u044F\u0454\u043C\u043E \u043E\u043D\u043E\u0432\u043B\u0435\u043D\u043D\u044F\u2026",
    current: "\u0423 \u0432\u0430\u0441 \u043D\u0430\u0439\u043D\u043E\u0432\u0456\u0448\u0430 \u0432\u0435\u0440\u0441\u0456\u044F.",
    available: "\u0417\u043D\u0430\u0439\u0434\u0435\u043D\u043E \u0432\u0435\u0440\u0441\u0456\u044E {version} \u2014 \u0437\u0430\u0432\u0430\u043D\u0442\u0430\u0436\u0443\u0454\u043C\u043E\u2026",
