    escortNeedsMilitary: "\u0414\u043B\u044F \u0441\u0443\u043F\u0440\u043E\u0432\u043E\u0434\u0443 \u043F\u043E\u0442\u0440\u0456\u0431\u0435\u043D \u043A\u043E\u0440\u0430\u0431\u0435\u043B\u044C \u0432\u043E\u0454\u043D\u043D\u043E\u0433\u043E \u043A\u043B\u0430\u0441\u0443.",
